function save(kind,record){freshStorage();const next=Core.apply(state,{kind,record,actor:current()?.operator||record.operator||record.entered_by||record.reviewer||'Operator',at:new Date().toISOString(),expected_revision:state.revision});persist(next);dirty=false;dirtyForms.clear();render();notify('Saved revision '+state.revision+'.');}
const id=kind=>kind+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
const current=()=>state.pilots.find(p=>p.id===pilotId)||null;
const records=kind=>state[kind].filter(r=>r.pilot_id===pilotId);
const option=(v,title,selected='')=>'<option value="'+esc(v)+'"'+(v===selected?' selected':'')+'>'+esc(title)+'</option>';
const select=(name,title,rows,value='',required=true)=>'<label>'+esc(title)+'<select name="'+esc(name)+'"'+(required?' required':'')+'>'+option('','Choose…',value)+rows.map(r=>option(r[0],r[1],value)).join('')+'</select></label>';
const input=(name,title,value='',type='text',required=false)=>'<label>'+esc(title)+'<input name="'+esc(name)+'" type="'+type+'" value="'+esc(value)+'"'+(required?' required':'')+(type==='number'?' step="any"':'')+'></label>';
const area=(name,title,value='',required=false)=>'<label class="wide">'+esc(title)+'<textarea name="'+esc(name)+'" rows="3"'+(required?' required':'')+'>'+esc(value)+'</textarea></label>';
const submit=text=>'<div class="wide"><button type="submit">'+esc(text)+'</button></div>';
const form=(kind,body)=>'<form id="'+kind+'-form" data-kind="'+kind+'" class="form">'+body+'</form>';
const enums=values=>values.map(v=>[v,label(v)]);
const download=(name,value,type='application/json')=>{const blob=new Blob([typeof value==='string'||value instanceof Uint8Array||value instanceof Blob?value:JSON.stringify(value,null,2)+'\n'],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
function metricHtml(m){return'<dl class="metrics">'+Object.entries({ 'Expected points':m.planned,'Evaluated points':m.evaluated,'Ranked':m.ranked,'Not found':m.not_found,'Errors':m.error,'Missing':m.missing,'Complete-grid top 3 (%)':m.top3_grid,'Top 3 among evaluated (%)':m.top3_evaluated,'Mean of ranked points':m.found_only_mean,'Best observed rank':m.best_rank}).map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(show(v))+'</dd></div>').join('')+'</dl>';}
function observationTitle(o){return o.provider+' · '+when(o.captured_at)+' · '+o.status+' · '+o.id.slice(-6);}
function shell(content){const pilot=current();$('#app').innerHTML='<header><div><p class="eyebrow">MapRank companion</p><h1>Agency pilot desk</h1><p>Original agency research, measurement planning and client handover</p></div><div class="actions"><button data-action="export">Save working file</button><label class="file-button">Open working file<input id="working-file" type="file" accept=".json,application/json"></label></div></header><div id="notice" data-revision="'+state.revision+'" class="notice" tabindex="-1" role="status">'+esc(storageWarning||'Working revision '+state.revision+' · '+seed.agencies.length+' original agency profiles')+'</div><nav aria-label="Workspace views">'+['Agencies','Pilots','Scope','Results','Review','Delivery','Guide'].map(t=>'<button data-tab="'+t+'" aria-current="'+(tab===t?'page':'false')+'">'+t+'</button>').join('')+'</nav><section class="case-bar">'+select('activePilot','Active client/location pilot',state.pilots.map(p=>[p.id,p.client+' — '+p.location]),pilotId,false)+'<p>'+esc(pilot?pilot.question:'Select a research profile and create a pilot with actual client inputs.')+'</p></section><main>'+content+'</main><footer>Complete local working files preserve original sources and history. Account actions and scans stay in your existing MapRank workflow. <button data-action="source">Download complete application source</button></footer>';
 $('#working-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text(),next=Core.receive(JSON.parse(text),seed);if(!discard())return;freshStorage();if(!confirm('Replace this browser working copy with the complete selected file? Existing history remains in your exported copy.'))return;persist(next);pilotId=state.pilots[0]?.id||'';dirty=false;dirtyForms.clear();render();notify('Opened all '+state.revision+' original operations.');}catch(err){notify(err.message,true);} };
 const active=$('select[name="activePilot"]');active.onchange=()=>{if(!discard()){active.value=pilotId;return;}pilotId=active.value;editingPilot='';editingFinding='';dirty=false;render();};
}
function agencies(){return'<h2>Choose an agency profile</h2><p>These are researched candidates. A pilot begins only when you enter its agreed client, location and scope.</p><div class="cards">'+seed.agencies.map(a=>'<article><h3>'+esc(a.document.organization)+'</h3><p>'+esc(a.document.geography)+'</p><h4>Existing workflow</h4><p>'+esc(a.document.demand)+'</p><h4>Suggested comparison</h4><p>'+esc(a.document.fit)+'</p><p><a href="'+href(a.document.source_url)+'" target="_blank" rel="noopener">Original service source</a></p><button data-plan="'+esc(a.id)+'">Plan a pilot</button></article>').join('')+'</div>';}
function pilots(){const p=state.pilots.find(x=>x.id===editingPilot)||{};return'<h2>Client and location</h2><p>Each pilot keeps one agency, client and physical location together. Create another pilot for another location.</p>'+form('pilot',select('agency_id','Agency',seed.agencies.map(a=>[a.id,a.document.organization]),p.agency_id||window.chosenAgency||'')+input('client','Client organization',p.client,'text',true)+input('location','Business/location name',p.location,'text',true)+input('address','Address',p.address)+input('place_id','Google Place ID',p.place_id)+input('provider_business_id','MapRank business ID',p.provider_business_id)+input('identity_source','Business identity source',p.identity_source)+select('identity_review','Identity review',enums(['unreviewed','matched','needs_correction']),p.identity_review||'unreviewed')+input('operator','Pilot operator',p.operator,'text',true)+input('reviewer','Reviewer',p.reviewer)+input('timezone','Reporting timezone',p.timezone||'UTC','text',true)+input('custody','Account owner / nonsecret access reference',p.custody)+area('question','Business question',p.question,true)+area('target','Agreed target or decision conditions',p.target)+submit(editingPilot?'Save client/location changes':'Create pilot'))+'<h3>Current pilots</h3>'+state.pilots.map(p=>'<article><h4>'+esc(p.client)+' — '+esc(p.location)+'</h4><p>'+esc(p.question)+'</p><button data-edit-pilot="'+esc(p.id)+'">Edit pilot</button></article>').join('');}
function scopeView(){if(!current())return'<h2>Select or create a pilot first</h2>';const a=records('accounts'),sc=records('scopes');return'<h2>Account and measurement scope</h2><p>Record what the account actually displays. Current and legacy plans can differ. A scope is immutable after saving; create a new version for any changed geography or keyword.</p><details open><summary>New account snapshot</summary>'+form('account',input('label','Account label','','text',true)+input('plan','Observed plan name','','text',true)+select('generation','Plan generation',enums(['current','legacy','unknown']),'unknown')+input('observed_at','Observed at',localTime(),'datetime-local',true)+input('source','Actual account/checkout source','','text',true)+input('owner','Account owner','','text',true)+input('grid_ceiling','Observed maximum grid side','','number')+input('balance','Monthly credits remaining','','number')+input('topup','Top-up credits remaining','','number')+select('custom_domain','Custom domain allowed',enums(['yes','no','unknown']),'unknown')+select('api_allowed','API scanning allowed',enums(['yes','no','unknown']),'unknown')+input('seats','Observed seat scope')+input('renewal','Renewal date','','date')+area('quote','Actual checkout/plan quote')+submit('Save account snapshot'))+'</details><details open><summary>New scope version</summary>'+form('scope',select('account_id','Account snapshot',a.map(x=>[x.id,x.label+' · '+x.plan+' · '+when(x.observed_at)]),a.at(-1)?.id||'')+select('supersedes','Previous scope (optional)',sc.map(x=>[x.id,x.keyword+' · '+x.id.slice(-6)]),'',false)+input('keyword','Exact keyword','','text',true)+input('rows','Grid rows',5,'number',true)+input('columns','Grid columns',5,'number',true)+input('center_latitude','Center latitude','','number')+input('center_longitude','Center longitude','','number')+input('spacing','Point spacing','','number')+select('unit','Spacing unit',enums(['km','mi','m','unknown']),'unknown')+input('expected_points','Expected points',25,'number',true)+input('depth','Received search depth','','number')+select('cadence','Planned cadence',enums(['one_off','weekly','biweekly','monthly','custom']),'one_off')+input('occurrences','Planned occurrences',1,'number',true)+input('budget','Chosen credit budget','','number')+area('points_text','Complete expected geometry: point id, latitude, longitude (tab-separated; no header). Leave empty for summary-only intake.')+area('reason','Why this keyword and geography?', '',true)+submit('Save new scope version'))+'</details><h3>Retained scope versions</h3>'+sc.map(x=>'<article><h4>'+esc(x.keyword)+' · '+x.rows+' × '+x.columns+'</h4><p>'+esc(x.reason)+'</p><p>'+x.points.length+' exact coordinates received · '+x.expected_points*x.occurrences+' estimated point credits · '+esc(label(x.cadence))+'</p><code>'+esc(x.id)+'</code></article>').join('');}
function resultsView(){if(!current())return'<h2>Select a pilot first</h2>';const scopes=records('scopes'),attachments=records('attachments'),obs=records('observations');return'<h2>Original result intake</h2><p>Keep the original file or report reference. Ranked, not found, error and missing are separate outcomes. A correction adds a new observation and keeps the original.</p><details><summary>Add an original source file (up to 5 MB)</summary>'+form('attachment','<label>Original file<input name="source_file" type="file" required></label>'+input('source','Original source or acquisition reference','','text',true)+select('visibility','Client selection',enums(['internal','client_selected']),'internal')+submit('Preserve original attachment'))+'</details><details open><summary>Add an observation</summary>'+form('observation',select('scope_id','Exact scope version',scopes.map(x=>[x.id,x.keyword+' · '+x.id.slice(-6)]),scopes.at(-1)?.id||'')+select('correction_of','Corrects original observation (optional)',obs.map(x=>[x.id,observationTitle(x)]),'',false)+input('correction_reason','Correction reason')+input('provider','Source provider','MapRank','text',true)+input('provider_scan_id','Actual scan ID')+select('mode','How received',enums(['original_file','provider_result','manual_transcription','summary_only']),'summary_only')+select('status','Reported scan status',enums(['completed','partial','failed']),'partial')+input('captured_at','Actual capture time','','datetime-local',true)+input('entered_by','Entered by',current().operator,'text',true)+input('source','Original report URL / source reference','','text',true)+select('attachment_id','Original file (optional)',attachments.map(x=>[x.id,x.name]),'',false)+input('average_rank','Vendor average rank — original text')+input('best_rank','Vendor best rank — original text')+input('top3_coverage','Vendor top 3 coverage — original text')+input('convention_source','Vendor missing-value convention source')+input('quote_credits','Actual quoted credits','','number')+input('actual_credits','Actual charged credits','','number')+area('points_text','Received points: id, latitude, longitude, outcome, rank (blank unless ranked), source, optional error (tab-separated; no header).')+area('notes','Internal intake notes')+submit('Save original observation'))+'</details><h3>Received observations</h3>'+obs.map(o=>'<article><h4>'+esc(observationTitle(o))+'</h4><p>Source: '+esc(o.source)+'</p><p>Original vendor values — mean: '+esc(show(o.provider_metrics.average_rank))+'; best: '+esc(show(o.provider_metrics.best_rank))+'; top 3: '+esc(show(o.provider_metrics.top3_coverage))+'</p>'+metricHtml(Core.metrics(state,o))+(o.correction_of?'<p>Corrects '+esc(o.correction_of)+': '+esc(o.correction_reason)+'</p>':'')+'</article>').join('')+'<h3>Original attachments</h3>'+attachments.map(a=>'<p>'+esc(a.name)+' · '+a.bytes+' bytes · '+esc(label(a.visibility))+' <button data-file="'+esc(a.id)+'">Download original</button></p>').join('');}
function reviewView(){if(!current())return'<h2>Select a pilot first</h2>';const obs=records('observations'),sc=records('scopes'),finding=state.findings.find(f=>f.id===editingFinding)||{};return'<h2>Comparison and client decision</h2><p>Equivalent geography and business identity are required for point-level comparisons. Summary-only records remain useful dated observations.</p>'+form('compare',select('baseline','Baseline',obs.map(o=>[o.id,observationTitle(o)]))+select('followup','Follow-up',obs.map(o=>[o.id,observationTitle(o)]))+submit('Compare received results'))+'<div id="comparison"></div><details><summary>'+esc(editingFinding?'Edit finding':'Add a finding / service action')+'</summary>'+form('finding',select('scope_id','Scope',sc.map(x=>[x.id,x.keyword]),finding.scope_id)+select('observation_id','Evidence observation',obs.map(o=>[o.id,observationTitle(o)]),finding.observation_ids?.[0])+input('title','Finding title',finding.title,'text',true)+area('observed','What was actually observed?',finding.observed,true)+area('hypothesis','Possible explanation — separate from observation',finding.hypothesis)+input('owner','Action owner',finding.owner)+area('action','Proposed / completed service action',finding.action)+input('due','Due date',finding.due,'date')+select('status','Action state',enums(['open','in_progress','done','deferred']),finding.status||'open')+submit(editingFinding?'Save finding changes':'Save finding'))+'</details>'+records('findings').map(f=>'<article><h4>'+esc(f.title)+'</h4><p>'+esc(f.observed)+'</p><p>'+esc(f.action)+' · '+esc(label(f.status))+'</p><button data-edit-finding="'+esc(f.id)+'">Edit finding</button></article>').join('')+'<h3>Record the actual client decision</h3>'+form('decision',select('baseline_id','Baseline reviewed',obs.map(o=>[o.id,observationTitle(o)]))+select('followup_id','Follow-up reviewed (optional)',obs.map(o=>[o.id,observationTitle(o)]),'',false)+select('outcome','Client decision',enums(['pending','continue_observation','approve_action','revise_scope','finish_pilot']),'pending')+input('decided_by','Actual decision maker')+input('decided_at','Decision time','','datetime-local')+input('next_date','Next review date','','date')+area('rationale','Decision rationale', '',true)+area('client_summary','Client-facing summary', '',true)+submit('Save decision against current revision'))+records('decisions').map(d=>'<article><h4>'+esc(label(d.outcome))+' · '+(Core.decisionCurrent(state,d)?'Current basis':'Review needed after changes')+'</h4><p>'+esc(d.client_summary)+'</p><p>'+esc(d.decided_by||'Decision pending')+' · '+esc(when(d.decided_at))+'</p></article>').join('');}
function deliveryView(){if(!current())return'<h2>Select a pilot first</h2>';const ds=records('decisions');return'<h2>Complete client handover</h2><p>Save the whole working file for continued editing. A client packet selects a completed current decision and only attachments explicitly marked for that client. Internal account custody and intake notes stay in the working record.</p>'+form('handover',select('decision_id','Current client decision',ds.map(d=>[d.id,label(d.outcome)+' · '+(Core.decisionCurrent(state,d)?'Current':'Review needed')]))+'<fieldset class="wide"><legend>Original attachments selected for the client</legend>'+records('attachments').filter(a=>a.visibility==='client_selected').map(a=>'<label class="check"><input type="checkbox" name="attachment_ids" value="'+esc(a.id)+'">'+esc(a.name)+'</label>').join('')+'</fieldset>'+submit('Download complete client packet'))+form('publication',select('decision_id','Decision source',ds.map(d=>[d.id,label(d.outcome)+' · revision '+d.basis_revision]))+select('status','Actual publication state',enums(['unpublished','approved','shared','withdrawn']),'unpublished')+input('report_url','Actual MapRank report URL')+input('recipient','Actual recipient')+input('reviewer','Sharing reviewer')+area('note','Sharing / receiving note')+submit('Record publication state'))+'<h3>Publication history</h3>'+records('publications').map(p=>'<article><h4>'+esc(label(p.status))+' · '+esc(when(p.at))+'</h4><p>'+esc(p.recipient||'No recipient entered')+' · '+esc(p.report_url||'No report URL entered')+'</p><p>'+esc(p.note)+'</p></article>').join('')+'<h3>Working history</h3><ol>'+state.history.filter(h=>h.record.pilot_id===pilotId||h.record.id===pilotId).map(h=>'<li>Revision '+h.revision+' · '+esc(label(h.kind))+' · '+esc(h.actor)+' · '+esc(when(h.at))+'</li>').join('')+'</ol>';}
function guide(){return'<h2>Operating guide and source register</h2><pre class="guide">'+esc(seed.guide)+'</pre><h3>Original official sources</h3>'+seed.sources.map(s=>'<article><h4><a href="'+href(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+'</a></h4><p>'+esc(s.finding)+'</p></article>').join('');}
function render(){if(pilotId&&!current())pilotId='';shell(({Agencies:agencies,Pilots:pilots,Scope:scopeView,Results:resultsView,Review:reviewView,Delivery:deliveryView,Guide:guide}[tab])());}
document.addEventListener('input',e=>{if(e.target.closest('form')){dirty=true;dirtyForms.add(e.target.closest('form').id);}});
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;
 const action=button.dataset.action;
 if(action==='export'){download('MapRank-'+(current()?.client||'agency')+'-working.json',state);notify('Complete working file downloaded, including every source attachment and original operation.');return;}
 if(action==='source'){download('MapRank-pilot-complete-source.json',JSON.parse($('#pilot-source').textContent));return;}
 if(button.dataset.file){const a=state.attachments.find(x=>x.id===button.dataset.file);download(a.name,Core.normalizeBase64(a.content_base64),a.media_type);return;}
 if(button.dataset.tab||button.dataset.plan||button.dataset.editPilot||button.dataset.editFinding){if(!discard())return;dirty=false;dirtyForms.clear();if(button.dataset.tab)tab=button.dataset.tab;if(button.dataset.plan){window.chosenAgency=button.dataset.plan;editingPilot='';tab='Pilots';}if(button.dataset.editPilot){editingPilot=button.dataset.editPilot;tab='Pilots';}if(button.dataset.editFinding){editingFinding=button.dataset.editFinding;tab='Review';}render();}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!f.dataset.kind)return;e.preventDefault();
 if([...dirtyForms].some(name=>name!==f.id)&&!confirm('Saving this form will discard unsaved changes in another form. Continue?'))return;
 const submitRevision=state.revision,submitPilot=pilotId;
 const data=new FormData(f),v=Object.fromEntries(data),kind=f.dataset.kind,existingDirty=dirty;
 for(const key of ['observed_at','captured_at','decided_at'])if(v[key])v[key]=new Date(v[key]).toISOString();
 const n=k=>v[k]===''||v[k]===undefined?null:Number(v[k]);
 try{
 if(kind==='compare'){const c=Core.compare(state,v.baseline,v.followup);$('#comparison').innerHTML='<article><h3>'+esc(label(c.status))+'</h3><p>'+esc(c.differences.join(', '))+'</p><p>Top 3 change: '+esc(show(c.top3_percentage_points))+' percentage points</p><div class="table-wrap"><table><thead><tr><th>Point</th><th>Baseline</th><th>Follow-up</th><th>Positions gained</th></tr></thead><tbody>'+c.joined.map(p=>'<tr><td>'+esc(p.point)+'</td><td>'+esc(p.baseline)+' '+esc(show(p.baseline_rank))+'</td><td>'+esc(p.followup)+' '+esc(show(p.followup_rank))+'</td><td>'+esc(show(p.positions_gained))+'</td></tr>').join('')+'</tbody></table></div></article>';return;}
 if(kind==='handover'){const ids=data.getAll('attachment_ids'),packet=Core.clientPacket(state,v.decision_id,ids);download('MapRank-client-handover.json',packet);download('MapRank-client-report.html',clientReport(packet),'text/html');notify('Client packet and readable report downloaded. Reopen the complete working file to continue editing.');return;}
 let r={id:id(kind),pilot_id:pilotId};
 if(kind==='pilot'){r={id:editingPilot||id(kind),...v};delete r.pilot_id;save(kind,r);pilotId=r.id;editingPilot='';render();return;}
 if(!current())throw Error('Select a pilot first.');
 if(kind==='account')Object.assign(r,v,{grid_ceiling:n('grid_ceiling'),balance:n('balance'),topup:n('topup')});
 if(kind==='scope'){Object.assign(r,v,{rows:n('rows'),columns:n('columns'),center_latitude:n('center_latitude'),center_longitude:n('center_longitude'),spacing:n('spacing'),expected_points:n('expected_points'),depth:n('depth'),occurrences:n('occurrences'),budget:n('budget'),points:Core.parsePoints(v.points_text),created_at:new Date().toISOString(),identity:Object.fromEntries(['client','location','address','place_id','provider_business_id'].map(k=>[k,current()[k]]))});delete r.points_text;}
 if(kind==='attachment'){const file=data.get('source_file');if(!file||file.size>5*1024*1024)throw Error('Choose one original file up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);Object.assign(r,{name:file.name,media_type:file.type||'application/octet-stream',content_base64:btoa(binary),bytes:bytes.length,sha256:window.PilotSha.sha256Bytes(bytes).sha256,source:v.source,received_at:new Date().toISOString(),visibility:v.visibility});}
 if(kind==='observation'){Object.assign(r,v,{points:Core.parsePoints(v.points_text,true),attachment_ids:v.attachment_id?[v.attachment_id]:[],provider_metrics:Object.fromEntries(['average_rank','best_rank','top3_coverage','convention_source'].map(k=>[k,v[k]])),quote_credits:n('quote_credits'),actual_credits:n('actual_credits')});for(const k of ['points_text','attachment_id','average_rank','best_rank','top3_coverage','convention_source'])delete r[k];}
 if(kind==='finding'){Object.assign(r,v,{id:editingFinding||r.id,observation_ids:[v.observation_id]});delete r.observation_id;}
 if(kind==='decision')Object.assign(r,v,{basis:Core.relevant(state,pilotId),basis_revision:state.revision});
 if(kind==='publication'){const d=state.decisions.find(d=>d.id===v.decision_id);if(!d)throw Error('Select a decision.');Object.assign(r,v,{source_revision:d.basis_revision,attachment_ids:[],at:new Date().toISOString()});}
 if(state.revision!==submitRevision||pilotId!==submitPilot)throw Error('Working selection changed during file intake. Select the original pilot and retry.');
 save(kind,r);if(kind==='finding'){editingFinding='';render();}
 }catch(err){dirty=existingDirty;notify(err.message,true);}
});
function clientReport(p){const b=p.baseline,met=p.baseline_metrics;return'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MapRank pilot report</title><style>body{font:16px/1.6 system-ui;color:#20252a;background:#fff;max-width:900px;margin:32px auto;padding:0 20px}h1,h2{line-height:1.2}p,td{overflow-wrap:anywhere}dt{font-weight:600}article{border:1px solid #ccd0d4;padding:18px;margin:20px 0}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px}.metrics div{border-top:1px solid #ddd;padding:8px}dd{margin:0}</style></head><body><h1>'+esc(p.client)+' — '+esc(p.location)+'</h1><p>'+esc(p.agency.name)+' · reviewed revision '+p.decision.basis_revision+'</p><article><h2>'+esc(label(p.decision.outcome))+'</h2><p>'+esc(p.decision.client_summary)+'</p><p>'+esc(p.decision.rationale)+'</p><p>'+esc(p.decision.decided_by)+' · '+esc(when(p.decision.decided_at))+'</p></article><h2>Original baseline</h2><p>'+esc(b.provider)+' · '+esc(when(b.captured_at))+' · '+esc(b.source)+'</p><p>Vendor average: '+esc(show(b.provider_metrics.average_rank))+'; top 3: '+esc(show(b.provider_metrics.top3_coverage))+'. Vendor conventions remain attached to their original source.</p>'+metricHtml(met)+(p.comparison?'<h2>Follow-up</h2><p>'+esc(label(p.comparison.status))+' · Complete-grid top 3 change: '+esc(show(p.comparison.top3_percentage_points))+' percentage points.</p>':'')+'<h2>Next review</h2><p>'+esc(p.decision.next_date||'No date agreed')+'</p><p>Complete selected source files and exact metrics accompany this report in the client JSON packet.</p></body></html>';}
window.addEventListener('beforeunload',e=>{if(dirty||storageWarning){e.preventDefault();e.returnValue='';}});
render();
})();

